from solution import longest_common_subsequence


def test_issue_example():
    """Example longest_common_subsequence("AGGTAB","GXTXAYB",6,7) == 4."""
    assert longest_common_subsequence("AGGTAB", "GXTXAYB", 6, 7) == 4  # LCS "GTAB": 1+1+1+1=4


def test_issue_both_empty():
    """Longest common subsequence of two empty sequences is 0."""
    assert longest_common_subsequence("", "", 0, 0) == 0  # no chars: 0+0=0


def test_issue_first_empty():
    """Longest common subsequence with empty X is 0."""
    assert longest_common_subsequence("", "ABC", 0, 3) == 0  # no chars: 0+0=0


def test_issue_second_empty():
    """Longest common subsequence with empty Y is 0."""
    assert longest_common_subsequence("ABC", "", 3, 0) == 0  # no chars: 0+0=0


def test_issue_identical():
    """Longest common subsequence of identical sequences is their length."""
    assert longest_common_subsequence("ABC", "ABC", 3, 3) == 3  # "ABC": 1+1+1=3


def test_issue_disjoint():
    """Longest common subsequence with no common characters is 0."""
    assert longest_common_subsequence("ABC", "DEF", 3, 3) == 0  # disjoint: 0+0=0


def test_issue_single_match():
    """Longest common subsequence of matching single characters is 1."""
    assert longest_common_subsequence("A", "A", 1, 1) == 1  # "A": 0+1=1


def test_issue_single_mismatch():
    """Longest common subsequence of differing single characters is 0."""
    assert longest_common_subsequence("A", "B", 1, 1) == 0  # mismatch: 1-1=0


def test_issue_scattered_match():
    """Longest common subsequence need not be contiguous."""
    assert longest_common_subsequence("ABCDEF", "ACE", 6, 3) == 3  # "ACE": 1+1+1=3


def test_issue_repeated_chars():
    """Longest common subsequence counts repeated characters correctly."""
    assert longest_common_subsequence("AAAA", "AA", 4, 2) == 2  # "AA": 1+1=2


def test_contract_m_prefix():
    """Parameter m limits X to its first m characters."""
    assert longest_common_subsequence("XYZABC", "ABC", 3, 3) == 0  # "XYZ" vs "ABC": 0+0=0


def test_contract_n_prefix():
    """Parameter n limits Y to its first n characters."""
    assert longest_common_subsequence("ABC", "XYZABC", 3, 3) == 0  # "ABC" vs "XYZ": 0+0=0
